def solve_sequence():
    # Initialize sequence with a_1 = 0
    a = {1: 0}

    # We need to calculate up to a_9 (since we need a_2 through a_9)
    N_max = 9

    results = {}

    for n in range(2, N_max + 1):
        max_val = -float('inf')
        best_i = []

        # Iterate through possible split points i, 1 <= i <= n - 1
        for i in range(1, n):
            # Calculate the term value
            min_term = min(i, n - i)
            current_val = a[i] + a[n - i] + min_term

            if current_val > max_val:
                max_val = current_val
                best_i = [i]
            elif current_val == max_val:
                best_i.append(i)

        a[n] = max_val
        results[n] = {"value": max_val, "indices": best_i}

    return results

results = solve_sequence()
print(results)

def calculate_a(n):
    if n == 1:
        return 0

    memo = {1: 0}

    def get_a(k):
        if k in memo:
            return memo[k]

        if k % 2 == 0:
            # n = 2k (even): a_n = 2a_{n/2} + n/2
            k_half = k // 2
            result = 2 * get_a(k_half) + k_half
        else:
            # n = 2k+1 (odd): a_n = a_k + a_{k+1} + k
            k_lower = k // 2
            k_upper = k // 2 + 1

            # k_lower is (n-1)/2
            result = get_a(k_lower) + get_a(k_upper) + k_lower

        memo[k] = result
        return result

    return get_a(n)

a2025 = calculate_a(2025)
print(f"a_2025: {a2025}")
